<?php $ch = curl_init('http://localhost:8080/api/auth/login'); curl_setopt($ch, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch, CURLOPT_POST, true); curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-Type: application/json', 'Accept: application/json']); curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode(['email'=>'admin@tengoktetangga.id','password'=>'Admin@2025!'])); $res = curl_exec($ch); $data = json_decode($res); if(!isset($data->access_token)) { echo 'LOGIN FAILED: '. $res; exit; } $token = $data->access_token; $ch2 = curl_init('http://localhost:8080/api/admin/dashboard'); curl_setopt($ch2, CURLOPT_RETURNTRANSFER, true); curl_setopt($ch2, CURLOPT_HTTPHEADER, ['Authorization: Bearer ' . $token, 'Accept: application/json']); echo curl_exec($ch2);
